const icons={calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M21 21v-3a6 6 0 0 0-3-5"/>',cut:'<circle cx="5" cy="6" r="3"/><circle cx="5" cy="18" r="3"/><path d="m8 8 13 13M8 16 21 3"/>',box:'<path d="m12 3 9 5v9l-9 5-9-5V8l9-5Zm0 9v10M3 8l9 4 9-4M8 5l9 5"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M21 10h-6v5h6M3 5l14-3v3"/>',chat:'<path d="M21 11a9 9 0 0 1-9 9 10 10 0 0 1-4-1l-5 2 1-5a9 9 0 1 1 17-5Z"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="16" cy="17" r="3"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>'};
function icon(name){return `<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.grid}</svg>`}
const menuIcons={overview:'grid',bookings:'calendar',clients:'users',barbers:'cut',services:'cut',products:'box',finance:'wallet',reminders:'chat',settings:'settings'};
let agendaDay=dateLocal();
const baseSwitchTab=switchTab;
switchTab=function(tab){baseSwitchTab(tab);document.querySelector('.admin-sidebar')?.classList.remove('is-open');if(tab==='overview')renderOverview();document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-current',b.dataset.tab===tab?'page':'false'))};
dashboard=async function(){modal.close();document.body.classList.add('admin-mode');document.getElementById('admin-app').hidden=false;location.hash='admin';document.getElementById('admin-app').innerHTML=`<aside class="admin-sidebar"><button class="admin-wordmark" onclick="exitAdmin()">barber<span>prime</span><small>ESPAÇO DO PROPRIETÁRIO</small></button><p class="side-caption">PRINCIPAL</p><nav aria-label="Navegação administrativa">${menu.map(m=>`<button data-tab="${m[0]}" onclick="switchTab('${m[0]}')">${icon(menuIcons[m[0]])}<span>${m[0]==='overview'?'Meu dia':m[2]}</span></button>`).join('')}</nav><div class="side-bottom"><button class="visit-site" onclick="exitAdmin()">Ver meu site ${icon('arrow')}</button><div class="owner-profile"><span>BP</span><div>Barber Prime<small>Administrador</small></div></div></div></aside><div class="admin-main"><header class="admin-top"><div><button class="menu-toggle" onclick="document.querySelector('.admin-sidebar').classList.toggle('is-open')" aria-label="Abrir menu">☰</button><span class="breadcrumb">Barber Prime <span>/</span> Gestão</span></div><div><button class="quiet-button" onclick="exitAdmin()">Ver site ↗</button><button class="quiet-button" onclick="loadAdmin()" aria-label="Atualizar dados">↻</button><button class="gold" onclick="book()">+ Novo agendamento</button></div></header><div id="admin-content"><p class="notice">Carregando agenda…</p></div></div>`;await loadAdmin()};
function shiftDay(offset){const date=new Date(agendaDay+'T12:00:00Z');date.setUTCDate(date.getUTCDate()+offset);agendaDay=date.toISOString().slice(0,10);renderOverview()}
function chooseDay(day){agendaDay=day;renderOverview()}
function prettyDay(day,options){return new Date(day+'T12:00:00Z').toLocaleDateString('pt-BR',{timeZone:'UTC',...options})}
function initials(name){return esc(name.trim().split(/\s+/).slice(0,2).map(n=>n[0]).join('').toUpperCase())}
function appointmentClass(status){return status==='Concluído'?'done':status==='Confirmado'?'confirmed':'pending'}
function appointmentDetails(id){const b=adminData.bookings.find(x=>x.id===id);if(!b)return;show(`<div class="modal-kicker">AGENDAMENTO</div><h2>${esc(b.name)}</h2><div class="appointment-detail"><p><span>Serviço</span><strong>${esc(b.serviceName)}</strong></p><p><span>Profissional</span><strong>${esc(b.barberName)}</strong></p><p><span>Horário</span><strong>${prettyDay(b.date,{day:'2-digit',month:'2-digit'})} · ${b.time}</strong></p><p><span>Valor</span><strong>${money(b.price)}</strong></p><p><span>Telefone</span><strong>${esc(b.phone)}</strong></p></div>${b.notes?`<p class="notice">${esc(b.notes)}</p>`:''}<label>Status do atendimento</label>${statusOptions(b)}${b.consent?`<button class="outline" onclick="reminder('${b.id}')">Preparar mensagem</button>`:''}`)}
function renderOverview(){if(!adminData)return;const rows=adminData.bookings.filter(b=>b.date===agendaDay&&!['Cancelado','Não compareceu'].includes(b.status)).sort((a,b)=>a.time.localeCompare(b.time));const done=rows.filter(b=>b.status==='Concluído'),pending=rows.filter(b=>b.status==='Pendente');const barbers=adminData.barbers.filter(b=>b.active);const totalDay=total(done,'price'),expected=total(rows.filter(b=>b.status!=='Concluído'),'price');const date=new Date(agendaDay+'T12:00:00Z'),weekday=date.getUTCDay();date.setUTCDate(date.getUTCDate()-((weekday+6)%7));let days='';for(let i=0;i<7;i++){const day=date.toISOString().slice(0,10);days+=`<button class="${day===agendaDay?'selected':''}" onclick="chooseDay('${day}')" aria-label="${prettyDay(day,{dateStyle:'full'})}" aria-pressed="${day===agendaDay}"><small>${prettyDay(day,{weekday:'short'}).replace('.','')}</small><strong>${day.slice(8)}</strong>${day===dateLocal()?'<span>Hoje</span>':'<span>&nbsp;</span>'}</button>`;date.setUTCDate(date.getUTCDate()+1)}
 const open=catalog.settings.open,close=catalog.settings.close,height=(close-open)*64;
 const lanes=barbers.map((b,i)=>{const items=rows.filter(x=>x.barber===b.id);return `<div class="schedule-lane"><div class="lane-heading"><span class="staff-avatar tone-${i%3}">${initials(b.name)}</span><div>${esc(b.name)}<small>${items.length} agendamento${items.length===1?'':'s'}</small></div></div><div class="lane-body" style="height:${height}px">${items.map(x=>{const start=Number(x.time.slice(0,2))*60+Number(x.time.slice(3)),top=(start-open*60)/60*64;return `<button class="appointment ${appointmentClass(x.status)}" style="top:${Math.max(0,top)}px;height:${Math.max(38,x.duration/60*64-4)}px" onclick="appointmentDetails('${x.id}')"><strong>${esc(x.name)}</strong><span>${x.time} · ${esc(x.serviceName)}</span></button>`}).join('')}${items.length?'':'<span class="lane-empty">Agenda livre</span>'}</div></div>`}).join('');
 const mobile=rows.map(b=>`<button class="mobile-appointment" onclick="appointmentDetails('${b.id}')"><time>${b.time}</time><div><strong>${esc(b.name)}</strong><small>${esc(b.serviceName)} · ${esc(b.barberName)}</small></div><span class="status-dot ${appointmentClass(b.status)}"></span></button>`).join('');
 document.querySelector('#admin-content').innerHTML=`<div class="day-heading"><div><span class="section-kicker">SUA BARBEARIA, EM ORDEM</span><h1>Vamos cuidar do dia.</h1><p>${prettyDay(agendaDay,{weekday:'long',day:'numeric',month:'long'})}</p></div><button class="outline" onclick="exportData('bookings')">Exportar agenda ↓</button></div><div class="daily-summary"><div><span>Agendamentos</span><strong>${rows.length.toString().padStart(2,'0')}</strong><small>${done.length} concluídos</small></div><div><span>Recebido em serviços</span><strong>${money(totalDay)}</strong><small>Atendimentos concluídos</small></div><div><span>Previsto para receber</span><strong>${money(expected)}</strong><small>Atendimentos em aberto</small></div><div><span>Aguardando confirmação</span><strong>${pending.length.toString().padStart(2,'0')}</strong><small>Na data selecionada</small></div></div><div class="workspace-grid"><section class="agenda-panel"><div class="agenda-title"><h2>Agenda</h2><div class="date-controls"><button onclick="shiftDay(-7)" aria-label="Semana anterior">‹</button><button onclick="chooseDay(dateLocal())">Hoje</button><button onclick="shiftDay(7)" aria-label="Próxima semana">›</button></div></div><div class="week-strip">${days}</div><div class="agenda-legend"><span><i class="confirmed"></i>Confirmado</span><span><i class="pending"></i>Pendente</span><span><i class="done"></i>Concluído</span></div><div class="schedule-scroll"><div class="schedule" style="grid-template-columns:54px repeat(${Math.max(1,barbers.length)},minmax(150px,1fr))"><div class="time-column"><div class="time-head"></div>${Array.from({length:close-open},(_,i)=>`<span>${String(open+i).padStart(2,'0')}:00</span>`).join('')}</div>${lanes||'<p class="notice">Cadastre um profissional para organizar a agenda.</p>'}</div></div><div class="mobile-agenda">${mobile||'<div class="empty-day"><h3>Um dia livre por aqui.</h3><p>Os agendamentos desta data aparecerão aqui.</p><button class="outline" onclick="book()">Adicionar agendamento</button></div>'}</div></section><aside class="day-aside"><section class="action-panel"><div class="panel-title"><h2>Para confirmar</h2><span class="count-badge">${pending.length}</span></div>${pending.length?pending.slice(0,5).map(b=>`<div class="pending-person"><div><strong>${esc(b.name)}</strong><small>${b.time} · ${esc(b.serviceName)}</small></div><button aria-label="Confirmar ${esc(b.name)}" onclick="changeStatus('${b.id}','Confirmado')">✓</button></div>`).join(''):'<div class="all-clear"><span>✓</span><h3>Tudo em dia.</h3><p>Nenhuma confirmação pendente nesta data.</p></div>'}</section><section class="action-panel"><h2>Equipe do dia</h2>${barbers.map((b,i)=>`<div class="team-row"><span class="staff-avatar tone-${i%3}">${initials(b.name)}</span><div><strong>${esc(b.name)}</strong><small>${rows.filter(x=>x.barber===b.id).length} atendimentos</small></div><button aria-label="Gerenciar ${esc(b.name)}" onclick="editRecord('barbers','${b.id}')">↗</button></div>`).join('')}</section><section class="whatsapp-note">${icon('chat')}<div><strong>Lembretes pelo WhatsApp</strong><p>Prepare as mensagens dos clientes que autorizaram o contato.</p><button onclick="switchTab('reminders')">Ver lembretes →</button></div></section></aside></div>`;
}
// A quieter storefront with a single clear booking action and live team details.
document.querySelector('.hero-content').innerHTML=`<p class="eyebrow">BARBEARIA · CORTE & BARBA</p><h1>Seu estilo.<br>Nosso ofício.</h1><p class="intro">Um bom corte faz diferença.<br>Escolha seu horário. O resto é com a gente.</p><div class="actions"><button class="gold" onclick="book()">Agendar um horário ${icon('arrow')}</button><a href="#servicos">Conhecer os serviços</a></div><p class="hero-footnote">Corte masculino &nbsp; / &nbsp; Barba &nbsp; / &nbsp; Cuidados</p>`;
document.querySelector('.signature')?.remove();
document.querySelector('header .logo').innerHTML='barber<span class="wordmark-prime">prime</span>';
document.querySelector('header nav').innerHTML='<a href="#servicos">Serviços</a><a href="#equipe">Equipe</a><a href="#loja">Produtos</a><a href="#planos">Clube Prime</a><a href="#contato">Contato</a>';
document.querySelector('header .cart').innerHTML=icon('box')+' <b id="count">0</b>';
document.querySelector('#servicos .section-heading').innerHTML='<div><p class="section-kicker">O QUE FAZEMOS</p><h2>Cuidado nos detalhes.</h2></div><span>Escolha seu serviço e encontre um horário.</span>';
document.querySelector('#loja .section-heading').innerHTML='<div><p class="section-kicker">PARA CONTINUAR EM CASA</p><h2>Essenciais de cuidado.</h2></div>';
document.querySelector('#galeria .section-heading').innerHTML='<div><p class="section-kicker">BARBER PRIME</p><h2>Nosso espaço.</h2></div>';
document.querySelector('#filters').hidden=true;
document.querySelector('#gallery').innerHTML='<img src="interior.png" alt="Ambiente de barbearia em tons escuros" loading="lazy">';
document.querySelector('#equipe').innerHTML='<p class="section-kicker">QUEM CUIDA DE VOCÊ</p><h2>Na cadeira certa.</h2><div id="public-team"></div>';
document.querySelector('.owner').innerHTML='<p class="section-kicker">ÁREA RESTRITA</p><h3>Gestão da barbearia</h3><button class="outline" onclick="dashboard()">Acessar painel →</button>';
const baseRenderCatalog=renderCatalog;
renderCatalog=function(){baseRenderCatalog();document.querySelector('#public-team').innerHTML=catalog.barbers.map((b,i)=>`<button class="public-staff" onclick="book()"><span class="staff-avatar tone-${i%3}">${initials(b.name)}</span><span>${esc(b.name)}<small>Escolher um horário</small></span>${icon('arrow')}</button>`).join('');const hours=document.querySelector('#contato strong')?.parentElement?.nextElementSibling?.querySelector('p');if(hours)hours.textContent=`Atendimento: ${String(catalog.settings.open).padStart(2,'0')}h às ${String(catalog.settings.close).padStart(2,'0')}h`;};
const dashboardWithDesign=dashboard;
function showAdminLogin(session){
 document.body.classList.add('admin-mode');const root=document.querySelector('#admin-app');root.hidden=false;location.hash='admin';adminData=null;
 const setup=!session.configured;
 root.innerHTML=`<div class="login-layout"><section class="login-photo"><button class="login-brand" onclick="exitAdmin()">barber<i>prime</i></button><div><span>BASTIDORES DA BARBER PRIME</span><h1>Bom trabalho<br>começa por aqui.</h1><p>Agenda, equipe e finanças.<br>Tudo no seu lugar.</p></div></section><section class="login-form-area"><button class="quiet-button back-link" onclick="exitAdmin()">← Voltar ao site</button><div class="login-form-wrap"><span class="section-kicker">ÁREA DO PROPRIETÁRIO</span><h2>${setup?'Crie seu acesso.':'Bem-vindo de volta.'}</h2><p>${setup?'Cadastre o e-mail e a senha que você usará para entrar no painel.':'Entre para cuidar da sua barbearia.'}</p>${session.provider==='chatgpt'?'<a class="gold" href="/signin-with-chatgpt?return_to=%2F%23admin" target="_top">Entrar com ChatGPT</a>':`<form id="admin-login-form">${setup&&session.setupKeyRequired?'<label for="login-setup-key">Código de instalação</label><input id="login-setup-key" type="password" autocomplete="off" required><small class="field-help">Use o ADMIN_SETUP_KEY definido na Vercel.</small>':''}<label for="login-email">E-mail</label><input id="login-email" type="email" autocomplete="username" placeholder="voce@exemplo.com" required maxlength="254"><label for="login-password">Senha</label><div class="password-field"><input id="login-password" type="password" autocomplete="${setup?'new-password':'current-password'}" required ${setup?'minlength="10"':''} maxlength="256"><button type="button" id="toggle-password" aria-label="Mostrar senha">Mostrar</button></div>${setup?'<small class="field-help">Use pelo menos 10 caracteres.</small><label for="login-confirm">Confirmar senha</label><input id="login-confirm" type="password" autocomplete="new-password" required minlength="10" maxlength="256">':''}<div class="form-error" id="login-error" role="alert"></div><button class="gold login-submit" type="submit">${setup?'Criar acesso e entrar':'Entrar no painel'} ${icon('arrow')}</button></form>`}<div class="login-footnote">Acesso reservado à administração da barbearia.</div></div></section></div>`;
 if(session.provider==='chatgpt')return;
 document.querySelector('#toggle-password').onclick=()=>{const field=document.querySelector('#login-password'),button=document.querySelector('#toggle-password');field.type=field.type==='password'?'text':'password';button.textContent=field.type==='password'?'Mostrar':'Ocultar';button.setAttribute('aria-label',button.textContent+' senha')};
 document.querySelector('#admin-login-form').onsubmit=async e=>{e.preventDefault();const password=document.querySelector('#login-password').value,email=document.querySelector('#login-email').value,button=e.target.querySelector('[type=submit]'),error=document.querySelector('#login-error');if(setup&&password!==document.querySelector('#login-confirm').value){error.textContent='As senhas não coincidem.';return}button.disabled=true;error.textContent='';try{await requestAPI(setup?'setup-login':'login',{email,password,setupKey:document.querySelector('#login-setup-key')?.value});e.target.reset();await dashboard()}catch(err){error.textContent=err.message;button.disabled=false}};
}
dashboard=async function(){modal.close();try{const session=await requestAPI('session');if(!session.authenticated){showAdminLogin(session);return}await dashboardWithDesign();const bottom=document.querySelector('.side-bottom');if(bottom)bottom.insertAdjacentHTML('beforeend','<button class="logout-button" onclick="logoutAdmin()">Sair da conta</button>')}catch(error){toast(error.message)}};
loadAdmin=async function(){try{const session=await requestAPI('session');if(!session.authenticated){showAdminLogin(session);return}adminData=await requestAPI('admin');switchTab(adminTab)}catch(error){toast(error.message)}};
async function logoutAdmin(){try{const session=await requestAPI('session');if(session.provider==='chatgpt'){location.href='/signout-with-chatgpt?return_to=%2F';return}await requestAPI('logout',{});adminData=null;await dashboard()}catch(error){toast(error.message)}}
